params.command:
$ErrorActionPreference='Stop'
$r='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
git -C $r fetch origin --prune | Out-Null
$targets=@(
'agent/bridge-uia-hardening-20260929',
'agent/bridge-uia-native-20260929',
'agent/swarm-contract-v3-20260929-0540',
'agent-bridge',
'fix/codex-quota-dispatch-circuit-20260929'
)
$worktreeBranches=@()
foreach($line in @(git -C $r worktree list --porcelain)){
  if($line -like 'branch refs/heads/*'){$worktreeBranches += $line.Substring(18)}
}
$deleted=@(); $missing=@(); $skipped=@()
foreach($b in $targets){
  if($b -in @('main','heaven-bridge')){throw "refusing reserved branch $b"}
  $remote=@(git -C $r ls-remote --heads origin "refs/heads/$b")
  if(-not $remote.Count){$missing += $b; continue}
  if($worktreeBranches -contains $b){$skipped += [pscustomobject]@{branch=$b;reason='active-local-worktree'};continue}
  git -C $r push origin --delete $b | Out-Host
  if($LASTEXITCODE -ne 0){throw "delete failed: $b"}
  $deleted += $b
}
git -C $r fetch origin --prune | Out-Null
[pscustomobject]@{deleted=$deleted;missing=$missing;skipped=$skipped;remaining=@(git -C $r for-each-ref --format='%(refname:strip=3)' refs/remotes/origin | Where-Object {$_ -and $_ -notin @('HEAD','main','heaven-bridge')})}|ConvertTo-Json -Depth 6
